import { useEffect, useRef, useState } from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import Header from "./components/Header";
import ContactList from "./components/ContactList";
import ContactDetail from "./components/ContactDetail";
import Register from "./components/Register";
import Login from "./components/Login";

import { getContacts, saveContact, updatePhoto } from "./api/ContactService";
import { toastError } from "./api/ToastService";

function App() {
  const modalRef = useRef();
  const fileRef = useRef();

  const [data, setData] = useState({});
  const [currentPage, setCurrentPage] = useState(0);
  const [file, setFile] = useState(undefined);
  const [isAuthenticated, setIsAuthenticated] = useState(
  !!localStorage.getItem("token")
);


  const [values, setValues] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    title: "",
    status: "",
  });

  /* ===================== AUTH CHECK ===================== */

const handleLogout = () => {
  localStorage.removeItem("token");
  setIsAuthenticated(false);
};


  /* ===================== CONTACT APIs ===================== */
  const getAllContacts = async (page = 0, size = 10) => {
    try {
      setCurrentPage(page);
      const { data } = await getContacts(page, size);
      setData(data);
    } catch (error) {
      console.error(error);
      toastError(error.message);
    }
  };

  const onChange = (e) => {
    setValues({ ...values, [e.target.name]: e.target.value });
  };

  const handleNewContact = async (e) => {
    e.preventDefault();
    try {
      const { data } = await saveContact(values);

      const formData = new FormData();
      formData.append("file", file);
      formData.append("id", data.id);

      await updatePhoto(formData);

      toggleModal(false);
      setFile(undefined);
      fileRef.current.value = null;
      setValues({
        name: "",
        email: "",
        phone: "",
        address: "",
        title: "",
        status: "",
      });

      getAllContacts();
    } catch (error) {
      console.error(error);
      toastError(error.message);
    }
  };

  const updateContact = async (contact) => {
    try {
      await saveContact(contact);
    } catch (error) {
      console.error(error);
      toastError(error.message);
    }
  };

  const updateImage = async (formData) => {
    try {
      await updatePhoto(formData);
    } catch (error) {
      console.error(error);
      toastError(error.message);
    }
  };

  /* ===================== MODAL ===================== */
  const toggleModal = (show) =>
    show ? modalRef.current.showModal() : modalRef.current.close();

  /* ===================== LOAD DATA ===================== */
  useEffect(() => {
  if (isAuthenticated) {
    getAllContacts();
  }
}, [isAuthenticated]);


  /* ===================== RENDER ===================== */
  return (
    <>



      <main className="main">
        <div className="container">
         <Routes>
  {/* App starts at Register */}
  <Route path="/" element={<Navigate to="/register" />} />

  {/* Auth routes */}
  <Route
    path="/register"
    element={isAuthenticated ? <Navigate to="/contacts" /> : <Register />}
  />

  <Route
  path="/login"
  element={
    isAuthenticated ? (
      <Navigate to="/contacts" />
    ) : (
      <Login setIsAuthenticated={setIsAuthenticated} />
    )
  }
/>


  {/* Protected routes */}
  <Route
    path="/contacts"
    element={
      isAuthenticated ? (
        <ContactList
          data={data}
          currentPage={currentPage}
          getAllContacts={getAllContacts}
        />
      ) : (
        <Navigate to="/login" />
      )
    }
  />

  <Route
    path="/contacts/:id"
    element={
      isAuthenticated ? (
        <ContactDetail
          updateContact={updateContact}
          updateImage={updateImage}
        />
      ) : (
        <Navigate to="/login" />
      )
    }
  />
</Routes>

        </div>
      </main>

      {/* ===================== MODAL ===================== */}
      <dialog ref={modalRef} className="modal">
        <div className="modal__header">
          <h3>New Contact</h3>
          <i
            onClick={() => toggleModal(false)}
            className="bi bi-x-lg"
          ></i>
        </div>

        <div className="divider"></div>

        <div className="modal__body">
          <form onSubmit={handleNewContact}>
            <div className="user-details">
              {["name", "email", "title", "phone", "address", "status"].map(
                (field) => (
                  <div className="input-box" key={field}>
                    <span className="details">{field}</span>
                    <input
                      type="text"
                      name={field}
                      value={values[field]}
                      onChange={onChange}
                      required
                    />
                  </div>
                )
              )}

              <div className="file-input">
                <span className="details">Profile Photo</span>
                <input
                  type="file"
                  ref={fileRef}
                  onChange={(e) => setFile(e.target.files[0])}
                  required
                />
              </div>
            </div>

            <div className="form_footer">
              <button
                type="button"
                className="btn btn-danger"
                onClick={() => toggleModal(false)}
              >
                Cancel
              </button>
              <button type="submit" className="btn">
                Save
              </button>
            </div>
          </form>
        </div>
      </dialog>

      <ToastContainer />
    </>
  );
}

export default App;
